text:
{
  "requirements": [
    {
      "id": "r1",
      "label": "Hosting Model Disclosure",
      "rfpQuote": "Bidder must disclose if it is proposing a Contractor Hosted or State Hosted application.",
      "section": "§4"
    },
    {
      "id": "r2",
      "label": "SLA Compliance Confirmation",
      "rfpQuote": "Bidder must confirm and describe how they will meet the requirements of SCHEDULE D – Service Level Agreement .",
      "section": "§4"
    },
    {
      "id": "r3",
      "label": "ADA WCAG 2.1 Compliance",
      "rfpQuote": "The Contractor must meet minimum ADA requirements Web Content Accessibility Guidelines (WCAG) 2.1.",
      "section": "§5"
    },
    {
      "id": "r4",
      "label": "Concurrent User Capacity",
      "rfpQuote": "Contractor Solution must meet the expected number of concurrent Users below.",
      "section": "§6"
    },
    {
      "id": "r5",
      "label": "MiLogin Identity Federation Integration",
      "rfpQuote": "The Contractor’s solution must implement identity federation with the State’s MiLogin IT Identity and Access Management (IAM) environment",
      "section": "§7"
    },
    {
      "id": "r6",
      "label": "User Access Audit Trail",
      "rfpQuote": "Create an audit trail of who, when, where, and what functions were accessed by a specific user.",
      "section": "§7.2"
    },
    {
      "id": "r7",
      "label": "Configurable Reporting Rules Engine",
      "rfpQuote": "Utilize a configurable reporting rules engine to determine the recipients of laboratory test result reports",
      "section": "§8.3"
    },
    {
      "id": "r8",
      "label": "Legacy Data Migration Strategy",
      "rfpQuote": "Contractor must develop a strategy for migrating the data identified in the table below:",
      "section": "§22"
    },
    {
      "id": "r9",
      "label": "Implementation and User Training",
      "rfpQuote": "The Contractor must provide administration and end-user training for implementation, go-live support, and operational handoff.",
      "section": "§24"
    },
    {
      "id": "r10",
      "label": "Transition In and Out Plan",
      "rfpQuote": "Bidder must provide a detailed transition-in and transition-out plan in Schedule G – Transition In and Out Plan",
      "section": "§25"
    },
    {
      "id": "r11",
      "label": "Comprehensive Solution Documentation",
      "rfpQuote": "Contractor must provide all user manuals, operating manuals, technical manuals and any other instructions, specifications, documents or materials",
      "section": "§26"
    },
    {
      "id": "r12",
      "label": "SUITE Methodology Utilization",
      "rfpQuote": "the Contractor is required to utilize the applicable State Unified Information Technology Environment (SUITE) methodologies",
      "section": "§33.1"
    },
    {
      "id": "r13",
      "label": "Milestone Work Breakdown Structure",
      "rfpQuote": "Bidder must submit a high-level project plan (Work Breakdown Structure) detailing how they will achieve the milestones",
      "section": "§33.2"
    },
    {
      "id": "r14",
      "label": "In-Person Project Kickoff Meeting",
      "rfpQuote": "the Contractor Project Manager must facilitate an in-person project kick off meeting with the support from the State’s Project Manager",
      "section": "§32"
    },
    {
      "id": "r15",
      "label": "Staff Background and Drug Screening",
      "rfpQuote": "Contractor must present certifications evidencing satisfactory ICHAT and drug test results for all staff identified for assignment to this project",
      "section": "§30"
    },
    {
      "id": "r16",
      "label": "Software Bill of Materials",
      "rfpQuote": "Contractor must provide a Software Bill of Materials (SBOM) containing details and supply chain relationships of various components",
      "section": "§20"
    },
    {
      "id": "r17",
      "label": "Application Response Time Standards",
      "rfpQuote": "The application must meet minimum performance measures or response times deemed acceptable by LIMS Administrators",
      "section": "§20.3"
    },
    {
      "id": "r18",
      "label": "Mandatory System-to-System Interfaces",
      "rfpQuote": "Contractor must interface their solution to the following technologies:",
      "section": "§21"
    },
    {
      "id": "r19",
      "label": "Financial Record Retention Audit",
      "rfpQuote": "Retain all financial and accounting records related to this Contract for a period of 7 years",
      "section": "§18"
    },
    {
      "id": "r20",
      "label": "Data Encryption Standards",
      "rfpQuote": "Ensure that State Data is encrypted in transit and at rest using FIPS validated AES encryption modules",
      "section": "§19.1"
    },
    {
      "id": "r21",
      "label": "Regulatory Standards Compliance",
      "rfpQuote": "Comply with all data processing requirements of CLIA, the College of American Pathologists (CAP), American Industrial Hygiene Association",
      "section": "§19.3"
    }
  ],
  "constraints": [
    {
      "id": "c1",
      "kind": "DEADLINE",
      "label": "Maximum Implementation Timeline Limit",
      "rfpQuote": "The State expects implementation to be completed no later than a year and half from Contract execution.",
      "section": "§33.2"
    },
    {
      "id": "c2",
      "kind": "LEGAL",
      "label": "Prohibition of Offshore System Access",
      "rfpQuote": "Contractor will not access State environments or State Systems from locations outside the United States",
      "section": "§20.2"
    },
    {
      "id": "c3",
      "kind": "LEGAL",
      "label": "Prohibition of Offshore Resources",
      "rfpQuote": "Use of Offshore Resources is prohibited per the Schedule E – Data Security Requirements.",
      "section": "§30"
    },
    {
      "id": "c4",
      "kind": "SCOPE",
      "label": "Concurrent User Capacity Ceiling",
      "rfpQuote": "The total number of concurrent users will not exceed 250 users.",
      "section": "§6"
    },
    {
      "id": "c5",
      "kind": "TECHNOLOGY",
      "label": "Domestic US Data Storage",
      "rfpQuote": "Store data within the United States.",
      "section": "§19.2"
    },
    {
      "id": "c6",
      "kind": "LEGAL",
      "label": "Prior Written Approval for Data Destruction",
      "rfpQuote": "Contractor will not dispose of, delete, or destroy State Data without the prior written approval of the State.",
      "section": "§18"
    },
    {
      "id": "c7",
      "kind": "LEGAL",
      "label": "Prohibition of Forced Labor",
      "rfpQuote": "The Contractor certifies that it will not furnish any Deliverable that was produced fully or partially by forced labor",
      "section": "§0"
    },
    {
      "id": "c8",
      "kind": "LEGAL",
      "label": "Mandatory GDBE Subcontracting Allocation",
      "rfpQuote": "at least 20% of that subcontracted work must be awarded to Michigan-based Geographically Disadvantaged Business Enterprises (GDBE).",
      "section": "§30"
    },
    {
      "id": "c9",
      "kind": "OTHER",
      "label": "State Business Hours Availability",
      "rfpQuote": "Contractor personnel must be available within the State’s business hours 8am-5pm, Eastern time, Monday through Friday.",
      "section": "§30"
    }
  ],
  "suggestedWeights": [
    {
      "criterionId": "problem_understanding",
      "weight": 2.0,
      "reason": "The State requires deep domain knowledge across diverse public health disciplines including clinical diagnostics, infectious disease, genomics, and toxicology."
    },
    {
      "criterionId": "scope_clarity",
      "weight": 2.5,
      "reason": "The RFP sets forth dozens of detailed technical tables and functional requirements that must each be designated by capability and configuration need."
    },
    {
      "criterionId": "pricing_clarity",
      "weight": 1.0,
      "reason": "Clear pricing is required across software licensing, hardware, subcontractor costs, and ongoing training support."
    },
    {
      "criterionId": "timeline_clarity",
      "weight": 2.0,
      "reason": "The RFP establishes a hard implementation cap of 1.5 years and requires a detailed milestone schedule tied to SUITE methodologies."
    },
    {
      "criterionId": "completeness",
      "weight": 2.5,
      "reason": "The worksheet demands explicit responses and exception logs for every numbered requirement, legal certification, and interface specification."
    },
    {
      "criterionId": "tone_persuasiveness",
      "weight": 1.0,
      "reason": "Responses must maintain a professional and compliant tone aligned with State of Michigan procurement standards."
    },
    {
      "criterionId": "risk_transparency",
      "weight": 2.0,
      "reason": "Bidders are explicitly instructed to identify the impacted risk for any customized or configured requirement across all functional areas."
    }
  ]
}
